package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import org.springframework.stereotype.Service;

/**
 * Reads a sheet's records back out of the audit file, newest first. It reads what the file holds;
 * it keeps no record of its own.
 */
@Service
public class AuditViewService {

    private final Audit audit;

    public AuditViewService(Audit audit) {
        this.audit = audit;
    }

    /**
     * The sheet's audit lines, newest first. With a name, only the lines about that person: those
     * carrying name=&lt;name&gt; or person=&lt;name&gt;, the name compared as names are (case and
     * surrounding spaces ignored).
     */
    public List<String> lines(String sheetId, String name) {
        Pattern sheet = Pattern.compile("(?:^| )sheet=" + Pattern.quote(sheetId) + "(?: |$)");
        String who = name == null ? "" : name.trim();
        Pattern person = who.isEmpty() ? null
                : Pattern.compile("(?:^| )(?:name|person)=" + Pattern.quote(who) + "(?= [A-Za-z][\\w-]*=|$)",
                        Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
        List<String> lines = new ArrayList<>();
        for (String line : audit.lines()) {
            if (sheet.matcher(line).find() && (person == null || person.matcher(line).find())) {
                lines.add(line);
            }
        }
        Collections.reverse(lines);
        return lines;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A claim template: a claim made from it takes its amount and note as they are at that moment. */
export interface ClaimTemplateView {
  id: number;
  name: string;
  amount: string;
  note: string;
}

// The active sheet's claim templates, re-read from the server each time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class ClaimTemplates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** By name. */
  readonly templates = signal<ClaimTemplateView[]>([]);
  private loads = 0;

  /** Re-read the active sheet's templates from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.templates.set([]);
    if (!user || !sid) return null;
    try {
      const templates = await firstValueFrom(
        this.http.get<ClaimTemplateView[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.templates.set(templates);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load claim templates (${e.status}).` : 'Could not load claim templates.';
    }
  }

  /** Save a template, replacing the one by its name; an error message when refused (a blank name, or an
   *  amount the claim form would refuse). */
  async save(name: string, amount: string, note: string): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const n = name.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!n) return 'Enter a template name.';
    if (!/^\d+(\.\d{1,2})?$/.test(amount.trim())) return 'Enter an amount of 0.00 or more with up to two decimals.';
    try {
      const saved = await firstValueFrom(
        this.http.post<ClaimTemplateView>(
          this.url(sid),
          { name: n, amount: amount.trim(), note: note.trim() },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.templates.update((ts) =>
          [...ts.filter((t) => t.name !== saved.name), saved].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)),
        );
      }
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string') return e.error.message;
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter an amount of 0.00 or more with up to two decimals.';
      return e instanceof HttpErrorResponse ? `Could not save claim template (${e.status}).` : 'Could not save claim template.';
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/claim-templates`;
  }
}
import { Component, inject, signal } from '@angular/core';
import { ClaimTemplates } from '../../core/claim-templates';

// The sheet's claim templates: a form saves one (saving a name again replaces it; a blank name, or an amount
// the claim form would refuse, is refused), and the list shows them. Each person's row makes a claim from one.
@Component({
  selector: 'app-claim-templates',
  template: `
    <section aria-label="Claim templates" data-testid="templates">
      <h2>Claim templates</h2>
      <form (submit)="save($event)" data-testid="template-form">
        <label for="template-form-name">Name</label>
        <input
          id="template-form-name"
          data-testid="template-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="template-form-amount">Amount</label>
        <input
          id="template-form-amount"
          data-testid="template-form-amount"
          inputmode="decimal"
          [value]="amount()"
          (input)="amount.set(value($event)); error.set(null)"
        />
        <label for="template-form-note">Note</label>
        <input
          id="template-form-note"
          data-testid="template-form-note"
          [value]="note()"
          (input)="note.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="template-form-submit" [disabled]="saving()">Save template</button>
        @if (error(); as err) {
          <p role="alert" data-testid="template-form-error">{{ err }}</p>
        }
      </form>
      <ul data-testid="template-list" aria-label="Claim templates">
        @for (t of templates.templates(); track t.id) {
          <li [attr.data-testid]="'template-row-' + t.name">
            <span data-testid="template-name">{{ t.name }}</span>
            <span data-testid="template-amount">{{ t.amount }}</span>
            <span data-testid="template-note">{{ t.note }}</span>
          </li>
        }
      </ul>
    </section>
  `,
})
export class ClaimTemplatesPanel {
  protected readonly templates = inject(ClaimTemplates);
  protected readonly name = signal('');
  protected readonly amount = signal('');
  protected readonly note = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async save(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.templates.save(this.name(), this.amount(), this.note());
      if (err) this.error.set(err);
      else {
        this.name.set('');
        this.amount.set('');
        this.note.set('');
      }
    } finally {
      this.saving.set(false);
    }
  }
}

