package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute naming the steward a user delegated the steward role acts for: each line of a
     *  change they make ends with for=<steward>, but for the lines that only report figures. */
    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";

    /** The events that only report figures, and so carry no for=. */
    private static final String[] FIGURES = { "ROLLUP ", "TOTALS ", "ALERT " };

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back (by any rule) writes nothing. Outside a transaction the record is written now.
     */
    public void recordOnCommit(String line) {
        String entry = line + actingFor(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    private static String actingFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
        if (steward == null) {
            return "";
        }
        for (String figures : FIGURES) {
            if (entry.startsWith(figures)) {
                return "";
            }
        }
        return " for=" + steward;
    }

    /** Every record the file holds now, in the order written (none when there is no file yet). */
    public synchronized List<String> lines() {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import net.officefloor.hq.app.history.History;

/** A person on a sheet, with a name and a dated grade (A, B or C): each grade they are given applies
 *  from a date, the first from the beginning of time. */
@Entity
@EntityListeners(History.class)
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades they were given, each from a date; the first has none. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonGrade> grades = new ArrayList<>();

    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** Their contact, trimmed and lower-cased; null when they have none. Unique on the sheet. */
    @Column(name = "contact")
    private String contact;

    /** The date they are retired from; null while not retired. Set at all, they count as retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds: an OPEN or PENDING claim dated within one, and bound by no statement, counts in no
     *  live total; their other claims still do. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonHold> holds = new ArrayList<>();

    /** The other names they go by. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonAlias> aliases = new ArrayList<>();

    /** Moved on by each save, so a save made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new PersonGrade(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades they were given, the one from the beginning of time first, then by from-date. */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on a date: the one whose from-date is the latest on or before it. */
    public String gradeOn(LocalDate date) {
        String found = null;
        for (PersonGrade g : getGrades()) {
            if (found == null || g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /** Give them a grade from a date, replacing the one they had from that same date. */
    public void setGrade(String grade, LocalDate from) {
        for (PersonGrade g : grades) {
            if (Objects.equals(g.getFromDate(), from)) {
                g.setGrade(grade);
                return;
            }
        }
        grades.add(new PersonGrade(grade, from));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether a claim on this date is refused: it is after their retirement date. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }

    /** Whether their retirement date is reached on a day (the sheet's today): it is on or before it. */
    public boolean retiredBy(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** Whether they have any hold at all. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Their holds, the one from the beginning of time first, then by from-date. */
    public List<PersonHold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(PersonHold::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder()))
                        .thenComparing(PersonHold::getToDate, Comparator.nullsLast(Comparator.naturalOrder())))
                .toList();
    }

    /** Whether a hold of theirs covers a date. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Put them on hold from a date, to a date when one is given. */
    public void hold(LocalDate from, LocalDate to) {
        holds.add(new PersonHold(from, to));
    }

    /** Their aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream().map(PersonAlias::getAlias)
                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(a -> a))
                .toList();
    }

    /** Give them another name they go by, stored trimmed. */
    public void addAlias(String alias) {
        aliases.add(new PersonAlias(sheetId, alias.trim()));
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in the order they were added. */
    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The person on the sheet with the name, ignoring case. */
    @Query("select p from Person p where p.sheetId = :sheetId and lower(p.name) = lower(:name)")
    Optional<Person> findByName(String sheetId, String name);

    /** The person on the sheet with the name or an alias equal to it, ignoring case. */
    @Query("select distinct p from Person p left join p.aliases a where p.sheetId = :sheetId"
            + " and (lower(p.name) = lower(:name) or lower(a.alias) = lower(:name))")
    Optional<Person> findByNameOrAlias(String sheetId, String name);

    /** Whether someone on the sheet other than {@code exceptId} has the name, ignoring case; or anyone on
     *  the sheet has it as an alias. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and (lower(p.name) = lower(:name)"
            + " and (:exceptId is null or p.id <> :exceptId)"
            + " or exists (select a from PersonAlias a where a.sheetId = :sheetId and lower(a.alias) = lower(:name)))")
    boolean nameTaken(String sheetId, String name, Long exceptId);

    /** Whether someone on the sheet other than {@code exceptId} has the contact. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and p.contact = :contact"
            + " and (:exceptId is null or p.id <> :exceptId)")
    boolean contactTaken(String sheetId, String contact, Long exceptId);
}
