        <app-claim-templates />
        <app-people />
        <app-paste-claims />
        <app-bulk-open />
        <app-bulk-settle />
        <app-bulk-reassign />
        <app-summary />
        <app-audit />
      }
    } @else {
      <form aria-label="Sign in" (submit)="signIn($event)">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
