 *  end), both inclusive. */
export interface Hold {
  from: string | null;
  to: string | null;
}

/** Whether one of the holds covers a date (YYYY-MM-DD). */
export function heldOn(holds: Hold[], date: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

